19	export async function generateMetadata({
20	  params,
21	}: {
22	  params: Promise<{ username: string }>;
23	}) {
24	  const { username } = await params;
25	  const [profile, locale, t] = await Promise.all([
26	    getUserByUsernameCached(username),
27	    getLocaleSafely(),
28	    getTranslations("Components.Profile"),
29	  ]);
30	
31	  if (!profile) {
32	    return { title: "Not Found" };
33	  }
34	
35	  // 2026-07-25 backend moved to `displayName`; keep `name` as a fallback
36	  // during the cut-over window so SEO titles don't render as "undefined".
37	  const displayName =
38	    profile.displayName?.trim() || profile.name?.trim() || profile.username;
39	  const title = t("title", { name: displayName });
40	  const description = t("metaDescription", { name: displayName });
41	  const canonical = toLocalizedUrl(`/perfil/${username}`, locale);
42	
43	  return buildPageMeta({
44	    title,
45	    description,
46	    canonical,
47	    image: `${siteUrl}/static/images/logo-seo-meta.webp`,
48	    locale,
49	    openGraphType: "profile",
50	  });
51	}
52	
53	export default async function ProfilePage({
54	  params,
55	}: {
56	  params: Promise<{ username: string }>;
57	}) {
58	  const { username } = await params;
59	
60	  const [profile, tBreadcrumbs, tProfile, locale] = await Promise.all([
61	    getUserByUsernameCached(username),
62	    getTranslations("Components.Breadcrumbs"),
63	    getTranslations("Components.Profile"),
64	    getLocaleSafely(),
65	  ]);
66	
67	  if (!profile) {
68	    notFound();
69	  }
70	
71	  const profileUrl = toLocalizedUrl(`/perfil/${profile.username}`, locale);
72	
73	  // 2026-07-25 backend migration: profile.displayName is canonical; profile.name
74	  // is the legacy field; profile.username is the safety net. Breadcrumb
75	  // schemas and the Person schema require string `name`, so coalesce.
76	  const profileDisplayName =
77	    profile.displayName?.trim() ||
78	    profile.name?.trim() ||
79	    profile.username?.trim() ||
80	    "";
