89	
90	  const personSchema = {
91	    "@context": "https://schema.org",
92	    "@type": "Person",
93	    name: profileDisplayName,
94	    url: profileUrl,
95	    identifier: profile.username,
96	  };
97	
98	  const tabItems = buildProfileTabItems(profile, tProfile);
99	
